
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_absp4_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_absp4", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([4.957912536636262e+01, 4.799425601334215e+01, 4.582540638672189e+01, 4.292129763670847e+01, 3.915192263462555e+01, 3.447183814070149e+01, 2.901389461916316e+01, 2.317567238387987e+01, 1.757317672301059e+01, 1.253206188534488e+01, 6.688792624090490e+00, 1.502450904629654e+00, 9.354708072773490e-01, 7.675040640029991e-01, 5.606799338606701e-01, 4.022678688108154e-01, 3.193791448947954e-01, 2.797901997061542e-01, 2.588716070048280e-01, 2.462914121382094e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


